@SubscribeMessage('realtime:request')
  async onRequest(
    @CurrentUser() user: CurrentUser,
    @MessageBody() envelope: RealtimeRequestEnvelope,
    @ConnectedSocket() client?: Socket
  ) {
    this.assertVersion(envelope.clientVersion);
    const handler = this.registry.getRequest(envelope.op);
    const input = handler.input.parse(envelope.input);
    return {
      data: await handler.handle(user, input as never, {
        connectionId: client?.id,
      }),
    };
  }

@SubscribeMessage('realtime:subscribe')
  async onSubscribe(
    @CurrentUser() user: CurrentUser,
    @ConnectedSocket() client: Socket,
    @MessageBody() envelope: RealtimeSubscribeEnvelope
  ) {
    this.assertVersion(envelope.clientVersion);
    const handler = this.registry.getTopic(envelope.topic);
    const input = handler.input.parse(envelope.input);
    await handler.authorize(user, input as never);
    const room = handler.room(user, input as never);
    await client.join(room);
    const subscriptionId = `${client.id}:${envelope.topic}:${getRealtimeInputKey(input)}`;
    this.subscriptions.set(subscriptionId, {
      socketId: client.id,
      room,
    });
    return { data: { subscriptionId } };
  }

@SubscribeMessage('realtime:unsubscribe')
  async onUnsubscribe(
    @ConnectedSocket() client: Socket,
    @MessageBody() envelope: RealtimeUnsubscribeEnvelope
  ) {
    this.assertVersion(envelope.clientVersion);
    if (!envelope.subscriptionId) {
      return { data: { ok: true } };
    }
    const subscription = this.subscriptions.get(envelope.subscriptionId);
    if (subscription?.socketId === client.id) {
      await client.leave(subscription.room);
      this.subscriptions.delete(envelope.subscriptionId);
    }
    return { data: { ok: true } };
  }

@SubscribeMessage('space:delete-doc')
  async onDeleteSpaceDoc(
    @ConnectedSocket() client: Socket,
    @CurrentUser() user: CurrentUser,
    @MessageBody() { spaceType, spaceId, docId }: DeleteDocMessage
  ): Promise<EventResponse<{ success: true }>> {
    docId = canonicalDocId(docId, spaceId);
    if (spaceType === SpaceType.Workspace) {
      await this.applyDocLifecycle(client, user.id, spaceId, docId, 'delete');
    } else {
      const adapter = this.selectAdapter(client, spaceType);
      await this.assertDocActionAllowed(
        spaceType,
        user.id,
        spaceId,
        docId,
        'Doc.Delete'
      );
      await adapter.delete(spaceId, docId);
    }
    return { data: { success: true } };
  }

@SubscribeMessage('space:doc-lifecycle')
  async onDocLifecycle(
    @ConnectedSocket() client: Socket,
    @CurrentUser() user: CurrentUser,
    @MessageBody() {
      spaceType,
      spaceId,
      docId,
      lifecycle,
      physicalDocId,
    }: DocLifecycleMessage
  ): Promise<EventResponse<{ timestamp: number; deletedDocIds?: string[] }>> {
    if (!['trash', 'restore', 'delete'].includes(lifecycle)) {
      throw new BadRequest('Invalid document lifecycle');
    }
    docId = canonicalDocId(docId, spaceId);
    if (spaceType !== SpaceType.Workspace) {
      throw new DocActionDenied({
        action: lifecycle === 'delete' ? 'Doc.Delete' : 'Doc.Update',
        docId,
        spaceId,
      });
    }
    return {
      data: await this.applyDocLifecycle(
        client,
        user.id,
        spaceId,
        docId,
        lifecycle,
        physicalDocId === undefined
          ? undefined
          : canonicalDocId(physicalDocId, spaceId)
      ),
    };
  }

